// Format de-identified program overview summary
const metrics = $input.first().json.data || {};
const reportDate = new Date().toLocaleDateString('en-US', {
  weekday: 'long',
  year: 'numeric',
  month: 'long',
  day: 'numeric'
});

const formattedReport = `
# CareFlow AI — Daily Program Summary Report
**Date**: ${reportDate}

## Operational Performance Metrics
- **Active Enrolled Clients**: ${metrics.active_clients || 0}
- **Upcoming Scheduled Visits**: ${metrics.appointments_scheduled || 0}
- **Completed Visits**: ${metrics.appointments_completed || 0}
- **Missed Appointments**: ${metrics.appointments_missed || 0}
- **Pending Care Follow-Ups**: ${metrics.followups_pending || 0}
- **Resolved Follow-Up Tasks**: ${metrics.followups_completed || 0}
- **Open Human Escalations**: ${metrics.escalations_open || 0}
- **Resolved Escalations**: ${metrics.escalations_resolved || 0}
- **Total Recorded Interactions**: ${metrics.interactions_count || 0}

*Note: This report strictly reflects aggregate operational counts with zero client-identifying or clinical health information.*
`.trim();

return [{
  json: {
    report_title: 'CareFlow AI Daily Program Summary',
    report_date: reportDate,
    metrics: metrics,
    formatted_report: formattedReport,
    generated_at: new Date().toISOString()
  }
}];
